<?php /** @var array{ready:bool,reason:string,used:int,cap:int} $status */ /** @var mixed $result */ /** @var mixed $tasks */ ?>
<div class="page-head"><div><p class="eyebrow">Assistant</p><h1>AI assistant</h1></div></div>
<div class="alert alert-ok" role="status"><p>The assistant writes <strong>drafts</strong>. It only sees records you are allowed to open, it never saves, sends or approves anything on its own, and it can be wrong — read everything before you use it. Requests are logged (who and how big, never the text).</p></div>
<?php if (!$status['ready']) : ?><div class="alert alert-error" role="status"><p><?= e($status['reason']) ?></p></div><?php endif; ?>
<?php if (is_array($result)) : ?><div class="panel"><h2><?= e((string) $result['title']) ?></h2><pre class="prewrap ai-output"><?= e((string) $result['text']) ?></pre></div><?php endif; ?>
<?php if (is_array($tasks)) : ?><div class="panel"><h2>Suggested tasks</h2><form method="post" action="/ai/tasks/create" class="form-grid"><?= csrf_field() ?><input type="hidden" name="project" value="<?= e((string) $tasks['project']) ?>">
    <?php foreach ($tasks['tasks'] as $i => $t) : ?><div class="field"><label class="check"><input type="checkbox" name="t[<?= (int) $i ?>][on]" value="1" checked> <strong><?= e($t['title']) ?></strong> <span class="muted">(<?= e($t['priority']) ?><?= $t['estimate_minutes'] ? ', ' . (int) $t['estimate_minutes'] . ' min' : '' ?>)</span></label>
        <input type="hidden" name="t[<?= (int) $i ?>][title]" value="<?= e($t['title']) ?>"><input type="hidden" name="t[<?= (int) $i ?>][description]" value="<?= e($t['description']) ?>"><input type="hidden" name="t[<?= (int) $i ?>][priority]" value="<?= e($t['priority']) ?>"><input type="hidden" name="t[<?= (int) $i ?>][estimate_minutes]" value="<?= e((string) ($t['estimate_minutes'] ?? '')) ?>">
        <?php if ($t['description'] !== '') : ?><p class="hint"><?= e($t['description']) ?></p><?php endif; ?></div><?php endforeach; ?>
    <div class="form-actions"><button class="btn btn-primary" type="submit">Create the ticked tasks</button></div></form></div><?php endif; ?>
<?php if ($status['ready']) : ?>
<div class="panel"><h2>Ask about your records</h2><form method="post" action="/ai" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="ask"><div class="field"><label for="q">Question</label><input id="q" name="question" required minlength="5" maxlength="300" value="<?= e(old('question')) ?>" placeholder="Which projects mention e-commerce?"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Ask</button></div></form></div>
<div class="panel"><h2>Summarise an enquiry</h2><form method="post" action="/ai" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="summarize"><div class="field"><label for="enq">Enquiry reference or ID (from the CRM address)</label><input id="enq" name="enquiry" required maxlength="40" value="<?= e(old('enquiry')) ?>"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Summarise</button></div></form></div>
<div class="panel"><h2>Project helpers</h2><form method="post" action="/ai" class="form-grid"><?= csrf_field() ?><div class="field"><label for="prj">Project ID (from the project address)</label><input id="prj" name="project" required maxlength="40" value="<?= e(old('project')) ?>"></div>
    <div class="form-actions"><button class="btn btn-primary" name="action" value="tasks" type="submit">Draft tasks</button> <button class="btn btn-ghost" name="action" value="next" type="submit">Suggest next steps</button></div></form></div>
<div class="panel"><h2>Draft a document</h2><form method="post" action="/ai" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="draft">
    <div class="field"><label for="kind">What</label><select id="kind" name="kind"><?php foreach (['email' => 'Email', 'proposal' => 'Short proposal', 'update' => 'Client status update', 'agreement' => 'Agreement wording (for a lawyer to review)'] as $k => $l) : ?><option value="<?= e($k) ?>"<?= old('kind') === $k ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="ins">What should it say?</label><textarea id="ins" name="instruction" rows="4" required minlength="10" maxlength="3000"><?= e(old('instruction')) ?></textarea></div>
    <div class="field"><label for="dprj">Project ID (optional, for context)</label><input id="dprj" name="project" maxlength="40" value="<?= e(old('project')) ?>"></div>
    <div class="form-actions"><button class="btn btn-primary" type="submit">Write a draft</button></div></form></div>
<?php endif; ?>
